package com.payslipmax.pdfparser.guide.model

import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable

/**
 * The text limits every Part II template must respect, shipped with the templates so Kotlin holds no second copy (`rules.json`).
 *
 * The Part II order templates and the rules they cite (this file) are generated by `docs/Plan/rule_cards/tools/part2_templates.py` from
 * `part2/rules.json` and the batch files in `part2/templates/`. Plain strings, ints and lists only, so the release build needs no keep
 * rule (`scripts/check_r8_guide.py` proves it). Narratives, authority lines and certificates are content (the manual's own wording), not
 * UI copy. `GuidePart2TemplateValidator` rechecks all of it on every load.
 */
@Serializable
data class Part2TemplateLimits(
    val narrative: Int,
    val label: Int,
    val help: Int,
    val slots: Int,
    val links: Int,
    val rules: Int,
    val note: Int,
)

/**
 * A rule the app implements: [kind] is `check` (a finding shown to the officer, with a [severity] of `warn` or `ack`) or `condition`
 * (decides whether a linked order applies). [basis] is `manual` with its [page] and [note], or `practice`. Logic stays in Kotlin;
 * only the id, severity and citation are content.
 */
@Serializable
data class Part2RuleDecl(
    val id: String,
    val kind: String,
    val severity: String? = null,
    val basis: String,
    val page: Int? = null,
    val note: String? = null,
)

/**
 * A question the officer answers once per event. [kind] is `date`, `number`, `text`, `ref` (an order number and date, used as `{id.no}`
 * and `{id.date}`) or `days` (counted for the officer [between] two date slots, both days included).
 */
@Serializable
data class Part2Slot(
    val id: String,
    val kind: String,
    val label: String,
    val help: String,
    val between: List<String> = emptyList(),
)

/** One column of an occurrence row (From, To, Data 1-4). [need] is `required`, `optional` or `none` (the manual leaves it empty). */
@Serializable
data class Part2Column(
    val need: String,
    val slot: String? = null,
)

/** An order that goes with another: [basis] `manual` cites [page] and [note]; `practice` cites none. [condition] names a rule that must hold. */
@Serializable
data class Part2Link(
    val code: String,
    val basis: String,
    val page: Int? = null,
    val note: String? = null,
    @SerialName("when") val condition: String? = null,
)

/**
 * The template for one code. [code] is the manual's; [print] replaces it on the slip only for REJOINAL (HRMS prints REJOIN). [rev] changes
 * whenever any shipped word does, so a printed draft can say the template was updated since. Each of [from], [to] and the four [data]
 * columns names a slot or is not required. [rules] are checks to run; [links] are the orders that go with this one.
 */
@Serializable
data class Part2Template(
    val code: String,
    val rev: String,
    val print: String? = null,
    val page: Int,
    val narrative: String,
    val slots: List<Part2Slot>,
    val from: Part2Column,
    val to: Part2Column,
    val data: List<Part2Column>,
    val authority: String? = null,
    val certificate: String? = null,
    val rules: List<String> = emptyList(),
    val links: List<Part2Link> = emptyList(),
)
